/**
 * GenArt Types
 *
 * Shared type definitions for the generative art engine.
 * These bridge the gap between audio-canvas's real audio data
 * and our procedural driver's synthetic data.
 */

// ============================================================================
// Audio Feature Types (synthetic, generated by ProceduralDriver)
// ============================================================================

export interface AudioFeatures {
  bass: number;              // 0-1, low frequency energy
  mid: number;               // 0-1, mid frequency energy
  high: number;              // 0-1, high frequency energy
  amplitude: number;         // 0-1, overall loudness
  centroid: number;          // 0-1, spectral centroid (pitch character)
  dominantFrequency: number; // 0-1, normalized dominant frequency
  frequencies: Uint8Array;   // Synthetic 1024-bin frequency array
}

export interface BeatInfo {
  onBeat: boolean;           // True for one frame at beat onset
  beatIntensity: number;     // 0-1, how strong this beat is
  bpm: number;               // Beats per minute
  normalizedTempo: number;   // 0-1, where 0=slow(40bpm), 1=fast(200bpm)
  isSaturated: boolean;      // True during sustained high-energy periods
}

// ============================================================================
// Tuner Parameters
// ============================================================================

export interface TunerParams {
  decay: number;        // 0-1, trail length (0=instant clear, 1=long trails)
  sensitivity: number;  // 0-1, reactivity threshold
  feedback: number;     // 0-1, self-reference amount
  bassWeight: number;   // 0-1, bass frequency multiplier
  midWeight: number;    // 0-1, mid frequency multiplier
  highWeight: number;   // 0-1, high frequency multiplier
  colorDrift: number;   // 0-1, hue shift speed over time
  chaos: number;        // 0-1, randomness/unpredictability
}

