// ============================================================================
// Energy Curves
// ============================================================================

export type EnergyCurveType =
  | 'steady'
  | 'build_up'
  | 'pulse'
  | 'chaotic'
  | 'calm_to_storm'
  | 'drop'
  | 'breathe';

// ============================================================================
// GenArt Config (stored per video)
// ============================================================================

export interface Keyframe {
  time: number;                    // Seconds into the video
  params: Partial<TunerParams>;    // Params to interpolate to
  easing?: 'linear' | 'ease-in' | 'ease-out' | 'ease-in-out';
}

export interface GenArtConfig {
  mode: string;                    // Mode ID from registry
  tunerParams: TunerParams;
  energyCurve: EnergyCurveType;
  bpm: number;
  pitch: number;                   // 0-1, base color character
  keyframes?: Keyframe[];          // Optional param changes over time
}

// ============================================================================
// Mode Metadata
// ============================================================================

export type ModeCategory = 'abstract' | 'geometric' | 'organic' | '3d';

export interface ModeInfo {
  id: string;
  name: string;
  description: string;
  category: ModeCategory;
  is3D: boolean;
}
